using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using MapSharedProps.EditorTools;
public static class Glass114Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Dictionary<string,GameObject> Import(string input,string tag,bool legacy=false){string folder="Assets/Imported114-"+tag;var result=new Dictionary<string,GameObject>();if(AssetDatabase.IsValidFolder(folder)){Check(tag=="valid","Only previously completed valid import can be resumed");foreach(var guid in AssetDatabase.FindAssets("t:Prefab",new[]{folder})){var path=AssetDatabase.GUIDToAssetPath(guid);result.Add(Path.GetFileNameWithoutExtension(path).Substring(6),AssetDatabase.LoadAssetAtPath<GameObject>(path));}Check(result.Count==44,"completed valid output count");return result;}AssetDatabase.CreateFolder("Assets","Imported114-"+tag);var parent=new GameObject(tag);int placed=legacy?LegacySmallProps114.Build(input,folder,parent.transform,Shader.Find("MapSharedProps/Lit"),result):SmallPropsV1.Build(input,folder,parent.transform,Shader.Find("MapSharedProps/Lit"),result);Check(placed==(tag=="valid"||tag=="library"?1:0),tag+" placed");UnityEngine.Object.DestroyImmediate(parent);return result;}
 public static void Run(){int exit=0;var output=Path.Combine(Root,"Evidence114Import");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
  string input=Path.Combine(Root,"Input114-after");var d=SmallPropsV1.Read(Path.Combine(input,"small_props.json"));Check(d.obsidianV1!=null,"optional valid");var valid=Import(input,"valid");Check(valid.Count==44,"44 prefabs");
  foreach(var id in valid.Keys.Where(id=>id!="obsidian")){var old=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported111-after-v3/small-"+id+".prefab");Check(old,"baseline "+id);Check(old.GetComponent<MeshFilter>().sharedMesh==valid[id].GetComponent<MeshFilter>().sharedMesh,"unchanged mesh "+id);int count=old.GetComponentsInChildren<Collider>(true).Length;Check(count==valid[id].GetComponentsInChildren<Collider>(true).Length,"collider count "+id);if(count>0)Check(ColliderSnapshot109.Capture(old)==ColliderSnapshot109.Capture(valid[id]),"unchanged collider "+id);else Check(id=="coiledrope"||SmallPropsV1.Read(Path.Combine(input,"small_props.json")).assets.First(a=>a.id==id).radius<=0,"intentional noncollision metadata "+id);}
  var current=valid["obsidian"];var visual=current.GetComponent<MeshFilter>().sharedMesh;var collision=current.GetComponent<MeshCollider>().sharedMesh;var a=d.obsidianV1.asset;var source=SmallPropsV1.MeshOf(a.positions,a.normals,a.colors,a.triangles,a.glow);
  Check(ColliderSnapshot109.MeshHash(source)==ColliderSnapshot109.MeshHash(collision)&&ColliderSnapshot109.MeshHash(source)==ColliderSnapshot109.MeshHash(visual),"40tri original positions/indices");Check(visual.normals.SequenceEqual(source.normals)&&visual.colors.SequenceEqual(source.colors),"original normals/colours");Check(visual.triangles.Length==120,"40 tri");UnityEngine.Object.DestroyImmediate(source);
  var renderer=current.GetComponent<Renderer>();var mat=renderer.sharedMaterial;Check(mat.shader.name=="Universal Render Pipeline/Lit"&&!ShaderUtil.ShaderHasError(mat.shader),"standard Lit compiles");Check(renderer.reflectionProbeUsage==ReflectionProbeUsage.BlendProbes&&!mat.IsKeywordEnabled("_EMISSION"),"reflection/nonemission");Check(mat.GetFloat("_Smoothness")==.9f&&mat.GetFloat("_Metallic")==.1f,"existing gloss values");Check(current.GetComponentsInChildren<Light>(true).Length==0,"no light");Check(mat.GetTexture("_BaseMap").width==128,"colour adapter 128");
  for(int i=0;i<225;i++){var o=UnityEngine.Object.Instantiate(current);Check(o.GetComponent<MeshFilter>().sharedMesh==visual&&o.GetComponent<Renderer>().sharedMaterial==mat,"shared resources");UnityEngine.Object.DestroyImmediate(o);}ColliderSnapshot109.NegativeControls(current);
  foreach(var tag in new[]{"missing","version","nonfinite","oversized"}){var folder=Path.Combine(Root,"Input114-"+tag);Check(Import(folder,tag).Count==43,tag+" keeps43");}
  Check(Import(Path.Combine(Root,"Input114-library"),"library").Count==44,"library reference");Check(Import(input,"legacy",true).Count==43,"previous reader keeps43 ignores optional");
  AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"prefabs\":44,\"other43MeshAndColliderExact\":true,\"original40Triangles\":true,\"normalsColoursExact\":true,\"nonemptyColliderNegativeControls\":true,\"sharedReferences\":225,\"missingInvalidVersionNonfiniteOversizedKeep43\":true,\"libraryReference\":true,\"legacyLogicKeeps43\":true,\"playerExecuted\":false}");
 }catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
